import numpy as np

def deterministic_split(n, seed, frac):
    '''Deterministic split of range(n) in permutation order.'''
    perm = np.random.default_rng(seed).permutation(n)
    n_test = int(round(frac * n))
    test_idx = [int(i) for i in perm[:n_test]]
    train_idx = [int(i) for i in perm[n_test:]]
    return train_idx, test_idx

def majority_baseline(y):
    '''Most frequent label; on ties the first label seen in y.'''
    counts = {}
    for label in y:
        counts[label] = counts.get(label, 0) + 1
    best = None
    for label in y:
        if best is None or counts[label] > counts[best]:
            best = label
    return best
